import re, sqlite3, pathlib
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
schema = {}
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    schema[t] = {c[1] for c in con.execute(f'PRAGMA table_info("{t}")')}
for (v,) in con.execute("select name from sqlite_master where type='view'"):
    try: schema[v] = {d[0] for d in con.execute(f'select * from "{v}" limit 0').description}
    except Exception: pass

files = [p for p in pathlib.Path('.').rglob('*.py')
         if 'migrations' not in str(p) and '_archived' not in str(p)
         and str(p).split('/')[0] in ('scripts','tools','schemas')]
ins = re.compile(r'INSERT\s+(?:OR\s+\w+\s+)?INTO\s+"?(\w+)"?\s*\(([^)]*)\)', re.I|re.S)
upd = re.compile(r'UPDATE\s+"?(\w+)"?\s+SET\s+([^"\']*?)(?:WHERE|$)', re.I|re.S)
bad = []
for p in files:
    src = p.read_text(errors='ignore')
    # join adjacent python string literals so split SQL still parses
    flat = re.sub(r'"\s*\n\s*"', '', re.sub(r"'\s*\n\s*'", '', src))
    for m in ins.finditer(flat):
        t, cols = m.group(1), m.group(2)
        if t not in schema: continue
        for c in re.findall(r'\b([a-z_][a-z0-9_]*)\b', cols):
            if c in ('VALUES','values','select','SELECT'): continue
            if c not in schema[t]:
                bad.append((str(p), t, c, 'INSERT'))
    for m in upd.finditer(flat):
        t, sets = m.group(1), m.group(2)
        if t not in schema: continue
        for c in re.findall(r'\b([a-z_][a-z0-9_]*)\s*=', sets):
            if c not in schema[t]:
                bad.append((str(p), t, c, 'UPDATE'))
seen=set(); 
for b in bad:
    if b in seen: continue
    seen.add(b); print(f"  {b[3]:6s} {b[1]}.{b[2]:24s} <- {b[0]}")
print("total distinct:", len(seen))
PY

