import ast, pathlib, sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tabs = {}
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    tabs[t] = {c[1] for c in con.execute(f'PRAGMA table_info("{t}")')}
# columns migration 085 removed, per the ALTER statements
gone = {"session","executed_at","worked_by_session","worked_at","attempted_by_session",
        "attempt_at","checked_by_session","checked_at","run_by_session",
        "verified_by_session","note","session_applied","last_updated"}
hits=[]
for p in pathlib.Path('.').rglob('*.py'):
    s=str(p)
    if 'migrations' in s or '_archived' in s: continue
    if s.split('/')[0] not in ('scripts','tools','schemas'): continue
    try: tree=ast.parse(p.read_text(errors='ignore'))
    except Exception: continue
    for n in ast.walk(tree):
        if not isinstance(n, ast.Dict): continue
        keys={k.value for k in n.keys if isinstance(k, ast.Constant) and isinstance(k.value,str)}
        if not keys: continue
        risky = keys & gone
        if not risky: continue
        # which table does this dict most look like?
        best=max(tabs, key=lambda t: len(keys & tabs[t]))
        ov=len(keys & tabs[best])
        if ov >= 3:
            missing = {k for k in keys if k not in tabs[best]}
            if missing & gone:
                hits.append((s, n.lineno, best, sorted(missing & gone), ov, len(keys)))
for h in sorted(set(hits)):
    print(f"  {h[0]}:{h[1]}  looks like {h[2]} ({h[4]}/{h[5]} cols match)  BAD KEYS: {h[3]}")
print("total:", len(set(hits)))
PY

